# Ansari Cheats — one-file installer (kisi bhi PC par ek baar Admin se chalao)
$ErrorActionPreference='Stop'
$dest="$env:APPDATA\AnsariCheats\launcher\scripts"
$ansari="$env:APPDATA\AnsariCheats"
$port=8765
$taskName='AnsariCheatsAutoLauncher'
$admin=([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if(-not $admin){Write-Host 'Admin PowerShell chahiye — Right click > Run as administrator' -ForegroundColor Red; exit 1}
New-Item -ItemType Directory -Force -Path $dest|Out-Null
$z=Join-Path $env:TEMP 'ansari.zip'
[IO.File]::WriteAllBytes($z,[Convert]::FromBase64String(''))
Expand-Archive -Path $z -DestinationPath $dest -Force
Remove-Item $z -Force -ErrorAction SilentlyContinue
foreach($f in @("$ansari\remote-server.pid","$ansari\launcher\watcher.lock")){if(Test-Path $f){try{Stop-Process -Id ([int](Get-Content $f -Raw).Trim()) -Force -EA SilentlyContinue}catch{}}}
Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -EA SilentlyContinue|Where-Object{$_.CommandLine -like '*remote-panel-server*' -or $_.CommandLine -like '*auto-launcher*Watch*'}|ForEach-Object{Stop-Process -Id $_.ProcessId -Force -EA SilentlyContinue}
Unregister-ScheduledTask -TaskName BlazeXiterAutoLauncher -Confirm:$false -ErrorAction SilentlyContinue
Start-Sleep -Seconds 2
netsh advfirewall firewall delete rule name="BlazeXiter Remote Panel" 2>$null|Out-Null
netsh advfirewall firewall delete rule name="Ansari Cheats Remote Panel" 2>$null|Out-Null
netsh advfirewall firewall add rule name="Ansari Cheats Remote Panel" dir=in action=allow protocol=TCP localport=$port|Out-Null
netsh http delete urlacl url="http://+:$port/" 2>$null|Out-Null
netsh http add urlacl url="http://+:$port/" user="$env:USERDOMAIN\$env:USERNAME"|Out-Null
$p=@{state='idle';message='Inject Panel dabao — emulator + Free Fire kholo';at=(Get-Date -Format o)}|ConvertTo-Json -Compress
[System.IO.File]::WriteAllText("$ansari\inject_status.json",$p,(New-Object System.Text.UTF8Encoding $false))
Remove-Item "$ansari\inject_request.json" -Force -ErrorAction SilentlyContinue
$ln=Join-Path $dest 'auto-launcher.ps1'
$taskArgs="-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$ln`" -Watch"
Register-ScheduledTask -TaskName $taskName -Action (New-ScheduledTaskAction -Execute powershell.exe -Argument $taskArgs) -Trigger (New-ScheduledTaskTrigger -AtLogOn -User $env:USERNAME) -Settings (New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1)) -RunLevel Highest -Force|Out-Null
Start-Process powershell.exe -ArgumentList @('-NoProfile','-WindowStyle','Hidden','-ExecutionPolicy','Bypass','-File',"`"$ln`"",'-Watch') -WindowStyle Hidden
Start-Sleep -Seconds 2
Start-Process powershell.exe -ArgumentList @('-NoProfile','-WindowStyle','Hidden','-ExecutionPolicy','Bypass','-File',"`"$(Join-Path $dest 'remote-panel-server.ps1')`"") -WindowStyle Hidden
$ip=(Get-NetIPAddress -AddressFamily IPv4 -EA SilentlyContinue|Where-Object{$_.IPAddress -notlike '127.*' -and $_.PrefixOrigin -ne 'WellKnown'}|Select-Object -First 1 -ExpandProperty IPAddress)
if(-not $ip){$ip='127.0.0.1'}
$url="http://${ip}:$port"
$url|Set-Content "$env:USERPROFILE\Desktop\mobile-panel-url.txt" -Encoding UTF8
$url|Set-Content "$ansari\phone-url.txt" -Encoding UTF8
try{Set-Clipboard -Value $url}catch{}
Write-Host ''; Write-Host '=== Ansari Cheats — SETUP DONE ===' -ForegroundColor Green
Write-Host "Phone URL: $url" -ForegroundColor Yellow
Write-Host 'Emulator + Free Fire kholo -> Web par Inject Panel -> Login (ansari / 66)' -ForegroundColor Cyan
